import "errors"

// Element is a node in the singly linked list.
type Element struct {
	value int
	next  *Element
}

// List is a singly linked list.
type List struct {
	head *Element
	size int
}

func New(elements []int) *List {
	l := &List{}
	for _, e := range elements {
		l.Push(e)
	}
	return l
}

func (l *List) Size() int {
	return l.size
}

func (l *List) Push(element int) {
	e := &Element{value: element, next: l.head}
	l.head = e
	l.size++
}

func (l *List) Pop() (int, error) {
	if l.head == nil {
		return 0, errors.New("pop from empty list")
	}
	v := l.head.value
	l.head = l.head.next
	l.size--
	return v, nil
}

func (l *List) Array() []int {
	result := make([]int, l.size)
	e := l.head
	for i := l.size - 1; i >= 0; i-- {
		result[i] = e.value
		e = e.next
	}
	return result
}

func (l *List) Reverse() *List {
	var prev *Element
	current := l.head
	for current != nil {
		next := current.next
		current.next = prev
		prev = current
		current = next
	}
	return &List{head: prev, size: l.size}
}
"}

